 launchMissile(siloId,x,y,owner=this.human,opts={}){const b=this.get(siloId);if(this.over||!b||b.kind!=='building'||b.type!=='silo'||b.owner!==owner||b.progress<1)return {ok:false,error:'請選擇已完工的我方'+this.buildingName('silo')};if(b.reload>0)return {ok:false,error:'裝填中（'+Math.ceil(b.reload)+' 秒）'};if(!this.inBounds(x,y))return {ok:false,error:'目標超出地圖'};const emp=!!opts.emp;if(emp&&!MODES[this.mode].scifi)return {ok:false,error:'只有科幻背景有 EMP 彈'};if(!this.exp[owner]?.[this.at(x,y)])return {ok:false,error:'目標在未探索的區域，先派偵察'};if(this.truce&&this.time<this.truce)return {ok:false,error:'休戰期間不能發射飛彈（還有 '+Math.ceil(this.truce-this.time)+' 秒）'};/* v2.7 續二（Helen「飛彈炸船沒事」）：爆炸只傷交戰中的敵方，瞄準自己人要擋、看不到敵人要警告，不然錢花了沒反應 */const R=emp?4:3;let warning=null;const seesHostile=this.unitsNear(x,y,R,u=>this.isHostile(owner,u.owner)&&this.vis[owner]?.[this.at(Math.floor(u.x),Math.floor(u.y))]).length>0||this.buildings.some(b=>b.hp>0&&this.isHostile(owner,b.owner)&&this.edgeDistance({x,y},b)<R&&this.exp[owner]?.[this.at(b.x,b.y)]);if(!seesHostile){const peaceful=this.unitsNear(x,y,R,u=>u.owner!==owner&&!this.isAllied(owner,u.owner)&&!this.isHostile(owner,u.owner)&&this.players[u.owner]?.status==='active')[0]||this.buildings.find(b=>b.hp>0&&b.owner!==owner&&!this.isAllied(owner,b.owner)&&!this.isHostile(owner,b.owner)&&this.players[b.owner]?.status==='active'&&this.edgeDistance({x,y},b)<R);if(peaceful)return {ok:false,error:'與'+this.playerName(peaceful.owner)+'停戰中，飛彈不會傷到他們；要打請先在勢力面板宣戰'};const friendly=this.unitsNear(x,y,1.5,u=>this.isAllied(owner,u.owner)).length>0||this.buildings.some(b=>b.hp>0&&this.isAllied(owner,b.owner)&&this.edgeDistance({x,y},b)<1);if(friendly)return {ok:false,error:'飛彈不會傷到自己人與盟友，請瞄準敵方單位或建築'};warning='目標附近看不到敵方單位或建築，飛彈可能白打'}const rn=MODES[this.mode].resources;const cost=emp?[0,0,100,120]:[0,0,150,80];if(!this.pay(owner,cost))return {ok:false,error:'資源不足（'+rn[2]+' '+cost[2]+'、'+rn[3]+' '+cost[3]+'）'};b.reload=BUILDINGS.silo.reload;const c=this.center(b);this.missiles.push({id:++this.id,owner,x:c.x,y:c.y,tx:x,ty:y,speed:9,done:false,check:0,emp});this.cue('launch',owner,c.x,c.y);return {ok:true,emp,warning}}
 updateMissile(m,dt){const d=distance(m,{x:m.tx,y:m.ty}),step=m.speed*dt;m.check+=dt;if(m.check>=.5){m.check=0;for(const b of this.buildings){if(b.hp<=0||b.progress<1||!BUILDINGS[b.type].antiAir||!this.isHostile(b.owner,m.owner))continue;if(distance(this.center(b),m)<BUILDINGS[b.type].range&&this.rand()<.4){m.done=true;this.effects.push({x:m.x,y:m.y,life:.4,type:'hit'});this.cue('intercept',m.owner,m.x,m.y);if(m.owner===this.human)this.log('飛彈被敵方防空攔截',m);return}}}if(d<=step){m.x=m.tx;m.y=m.ty;m.done=true;if(m.emp)this.empBlast(m.tx,m.ty,4,m.owner);else this.explode(m.tx,m.ty,3,m.owner,120,250);return}m.x+=(m.tx-m.x)/d*step;m.y+=(m.ty-m.y)/d*step}
 // EMP：半徑內敵方陸海單位停擺 8 秒、護盾歸零、燃料中的飛機不受影響；不造成生命傷害。
 empBlast(x,y,r,owner){this.cue('emp',owner,x,y);this.effects.push({x,y,life:.6,type:'emp'});let n=0;for(const u of this.unitsNear(x,y,r,u=>this.isHostile(owner,u.owner)&&u.domain!=='air')){u.stun=Math.max(u.stun||0,8);u.shield=0;u.lastHit=this.time;u.path=[];n++}if(owner===this.human)this.log('EMP 命中 '+n+' 個單位');return n}
