 boardOrder(ids,transportId,owner=this.human){const t=this.get(transportId);if(!t||t.kind!=='unit'||!t.cargo||!this.isAllied(owner,t.owner))return {ok:false,error:'請選擇我方'+this.unitName(5)};const free=UNIT[t.type].capacity-t.cargo.length;if(free<=0)return {ok:false,error:'船已載滿'};const picked=ids.filter(id=>{const u=this.get(id);return u&&u.kind==='unit'&&u.owner===owner&&u.domain==='land'&&!u.inside}).slice(0,free);if(!picked.length)return {ok:false,error:'沒有可登船的陸上單位'};this.order(picked,{kind:'board',target:t.id});return {ok:true,count:picked.length}}
