 unload(buildingId,owner=this.human){const b=this.get(buildingId);if(!b||b.kind!=='building'||!this.isAllied(owner,b.owner)||!b.garrison?.length)return {ok:false,error:'沒有駐軍'};let n=0;for(const id of b.garrison.slice()){const u=this.get(id);if(!u){b.garrison=b.garrison.filter(x=>x!==id);continue}const q=this.freeSpotAround(b,u.owner);if(!q)break;u.x=q.x;u.y=q.y;u.inside=null;u.task={kind:'idle'};u.path=[];this.bucketAdd(u);b.garrison=b.garrison.filter(x=>x!==id);n++}return {ok:n>0,count:n,error:n?undefined:'周圍沒有空位'}}
