 // 城鎮警報：附近村民躲進最近有空位的主城／防塔；解除警報則全部卸載。
 alarm(owner=this.human){const p=this.players[owner];if(!p||p.status!=='active')return {ok:false,error:'勢力不存在'};if(owner===this.human)this.cue('bell',owner);const shelters=this.buildings.filter(b=>b.owner===owner&&b.hp>0&&b.progress>=1&&this.garrisonCapacity(b)>0);if(!shelters.length)return {ok:false,error:'沒有可躲避的建築'};const free=new Map(shelters.map(b=>[b.id,this.garrisonCapacity(b)-b.garrison.length]));let n=0;for(const u of this.units){if(u.owner!==owner||u.hp<=0||u.inside||u.type!==0)continue;let best=null,bd=Infinity;for(const b of shelters){if(free.get(b.id)<=0)continue;const d=distance(this.center(b),u);if(d<25&&d<bd){bd=d;best=b}}if(!best)continue;free.set(best.id,free.get(best.id)-1);this.order([u.id],{kind:'garrison',target:best.id});n++}p.alarm=true;return {ok:true,count:n}}
