 cancelBuilding(id,owner=this.human){const b=this.get(id);if(!b||b.kind!=='building'||b.owner!==owner||this.over)return {ok:false,error:'沒有可取消的建築'};if(b.progress>=1)return {ok:false,error:'已完工的建築請用拆除'};const refund=BUILDINGS[b.type].cost.map(n=>Math.floor(n*(1-b.progress)));refund.forEach((n,i)=>this.res[owner][i]+=n);for(const u of this.units)if(u.task.kind==='build'&&u.task.target===b.id)u.task={kind:'idle'};b.hp=0;this.refreshBlocked();return {ok:true,refund}}
