 placeLandmarks(){const n=this.match.rules.landmarks;const cells=[...this.mainland].filter(i=>this.walkable(i%this.W+.5,Math.floor(i/this.W)+.5)&&!this.bases.some(b=>distance(b,{x:i%this.W,y:Math.floor(i/this.W)})<12));let tries=0;while(this.landmarks.length<n&&tries++<4000){const i=cells[Math.floor(this.rand()*cells.length)],x=i%this.W+.5,y=Math.floor(i/this.W)+.5;if(this.landmarks.some(l=>distance(l,{x,y})<Math.max(14,Math.sqrt(this.mainlandCells)/3)))continue;if(!this.walkable(x,y))continue;this.landmarks.push({id:++this.id,kind:'landmark',x,y,holder:null,contest:null,progress:0,hp:1});}}
